  return x + y;
}

int hijau(int x, int y) {
  return x - y;
}

int berhiber(int x, int y) {
  if (y == 0) {
    return 0;
  } else {
    return bersih(x, y) + hijau(x, y) + berhiber(x - 1, y - 1);
  }
}

